    def apply_header_banner(ws, theme_color, title_text, subtitle_text):
        ws.views.sheetView[0].rightToLeft = True
        ws.sheet_properties.tabColor = theme_color
        
        ws.merge_cells("A1:K1")
        title_cell = ws["A1"]
        title_cell.value = title_text
        title_cell.font = Font(name="Segoe UI", size=15, bold=True, color=white)
        title_cell.fill = PatternFill(start_color=theme_color, end_color=theme_color, fill_type="solid")
        title_cell.alignment = Alignment(horizontal="center", vertical="center")
        ws.row_dimensions[1].height = 36
        
        ws.merge_cells("A2:K2")
        sub_cell = ws["A2"]
        sub_cell.value = subtitle_text
        sub_cell.font = Font(name="Segoe UI", size=9.5, italic=True, color="444444")
        sub_cell.fill = PatternFill(start_color="EAEDED", end_color="EAEDED", fill_type="solid")
